                DeckCard(english: "To make up after a fight", spanish: "Hacer las paces", notes: "Lit: \"To make the peaces.\" The reconciliation moment after an argument. \"Ya hicimos las paces\" = We made up.", targetLang: "es"),
                DeckCard(english: "Long distance relationship", spanish: "Relación a distancia", notes: "Direct equivalent. Comes with the same eye rolls in any language.", targetLang: "es"),
                DeckCard(english: "To be exclusive", spanish: "Ser exclusivos", notes: "\"¿Somos exclusivos?\" = Are we exclusive? The \"what are we?\" conversation outcome.", targetLang: "es"),
                DeckCard(english: "To reject / ghost someone", spanish: "Dar calabazas", notes: "Lit: \"To give them pumpkins.\" The calabaza is historically a symbol of rejection in Spanish. \"Me dio calabazas\" = She rejected me.", targetLang: "es"),
                DeckCard(english: "To be crazy about someone", spanish: "Estar colado/a", notes: "\"Estoy colado por ella\" (m) / \"Estoy colada por él\" (f). Lit: \"to be filtered through\" — implies you can't think straight.", targetLang: "es"),
